#include <vector>
#include <stack>
using namespace std;

class Solution {
public:
    int maxWidthRamp(vector<int>& A) {
        stack<int> stk;
        for (int i = 0; i < A.size(); ++i) {
            if (stk.empty() || A[stk.top()] > A[i]) stk.push(i);
        }

        int maxRamp = 0;
        for (int i = A.size() - 1; i >= 0; --i) {
            while (!stk.empty() && A[i] >= A[stk.top()]) {
                maxRamp = max(maxRamp, i - stk.top());
                stk.pop();
            }
        }

        return maxRamp;
    }
};
